CREATE TABLE residence_photos (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), object_key TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id));
ALTER TABLE condominiums ADD COLUMN residence_kind TEXT NOT NULL DEFAULT 'collective';
ALTER TABLE condominiums ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE condominiums ADD COLUMN photo_id TEXT REFERENCES residence_photos(id);
ALTER TABLE condominiums ADD COLUMN profile_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE condominiums ADD COLUMN updated_by TEXT REFERENCES users(id);
ALTER TABLE condominiums ADD COLUMN updated_at TEXT;
CREATE TABLE annual_budgets (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), fiscal_year INTEGER NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0 AND amount_cents<=100000000), notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, UNIQUE(condominium_id,fiscal_year));
CREATE TABLE expense_invoices (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), fiscal_year INTEGER NOT NULL, title TEXT NOT NULL, supplier TEXT NOT NULL, invoice_date TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0 AND amount_cents<=100000000), paid_cents INTEGER NOT NULL DEFAULT 0 CHECK(paid_cents>=0 AND paid_cents<=amount_cents), cancelled INTEGER NOT NULL DEFAULT 0 CHECK(cancelled IN (0,1)), notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE INDEX expense_context ON expense_invoices(condominium_id,fiscal_year,invoice_date);
CREATE TRIGGER residence_updated AFTER UPDATE OF name,address,residence_kind,description,photo_id ON condominiums WHEN NEW.updated_by IS NOT NULL BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.id,NEW.updated_by,'residence_updated',NEW.id,NEW.profile_version,NEW.updated_at); END;
CREATE TRIGGER budget_created AFTER INSERT ON annual_budgets BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'budget_created',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER budget_updated AFTER UPDATE ON annual_budgets BEGIN INSERT INTO item_revisions(resource_id,condominium_id,actor_id,version,snapshot,happened_at) VALUES(OLD.id,OLD.condominium_id,NEW.updated_by,OLD.version,json_object('amountCents',OLD.amount_cents,'notes',OLD.notes,'fiscalYear',OLD.fiscal_year),NEW.updated_at); INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'budget_updated',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER expense_created AFTER INSERT ON expense_invoices BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'invoice_created',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER expense_updated AFTER UPDATE ON expense_invoices BEGIN INSERT INTO item_revisions(resource_id,condominium_id,actor_id,version,snapshot,happened_at) VALUES(OLD.id,OLD.condominium_id,NEW.updated_by,OLD.version,json_object('title',OLD.title,'supplier',OLD.supplier,'invoiceDate',OLD.invoice_date,'amountCents',OLD.amount_cents,'paidCents',OLD.paid_cents,'cancelled',OLD.cancelled,'notes',OLD.notes),NEW.updated_at); INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'invoice_updated',NEW.id,NEW.version,NEW.updated_at); END;
